drop schema if exists test cascade;
create schema test;

set search_path='test',public;

drop table if exists test.orig;
create table orig (
  oid serial,
  country_code varchar,
  geom geometry(polygon, 3035)
);

alter table orig add constraint pk__orig primary key (oid);
create index sidx__orig on orig using gist (geom);

